      "id": "2",
      "type": "google-search",
      "param": {
        "query": "book: {{#1.book#}} author: {{#1.author#}}"
      }
    },
    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [["search_results", ["json", "2"]]],
        "outputs": [["extracted_text", "string"]],
        "code": "def main(search_results: dict):\n\ttext = \"\"\n\tfor result in search_results.get('organic_results', []):\n\t\ttext += result['snippet'] + \"\\n\\n\"\n\treturn {\"extracted_text\": text}"
      }
