    {
      "id": "4",
      "type": "llm",
      "param": {
        "system": "Summarize the following text into a three-minute read. Focus on key plot points, themes, and character development.",
        "user": "Please generate a concise summary of the book '{{#1.book#}}' by {{#1.author#}} based on this content: {{#3.extracted_text#}}"
      }
    },
    {
      "id": "5",
      "type": "end",
      "param": {
        "outputs": [["result", ["text", "4"]]]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"],
    ["3", 0, "4"],
    ["4", 0, "5"]
  ]
}

